-- ============================================
-- LUMA — Thème 6 : MOYEN 1/3 x4 — Une visite d'appartement en colocation
-- ============================================


update scenarios set content = '{"characters": {"current_roommate": "le/la colocataire actuel(le)"}, "start_node": "n1", "nodes": {"n1": {"speaker": "current_roommate", "text": "Hi, thanks for coming! So, tell us a bit about yourself.", "text_fr": "Salut, merci d''être venu ! Alors, parle-nous un peu de toi.", "choices": [{"text": "Sure! I work in graphic design and I''m pretty tidy and quiet.", "text_fr": "Bien sûr ! Je travaille en design graphique et je suis plutôt ordonné et calme.", "next": "n2"}, {"text": "Of course, I''m a grad student, and I love cooking for others.", "text_fr": "Bien sûr, je suis étudiant en master, et j''adore cuisiner pour les autres.", "next": "n2b"}]}, "n2": {"speaker": "current_roommate", "text": "Nice, and what''s your schedule usually like?", "text_fr": "Cool, et ton emploi du temps ressemble à quoi habituellement ?", "choices": [{"text": "Pretty standard, 9 to 5 on weekdays.", "text_fr": "Assez standard, 9h-17h en semaine.", "next": "n3"}, {"text": "I work from home most days, so I''m around a lot.", "text_fr": "Je travaille de chez moi la plupart du temps, donc je suis souvent là.", "next": "n3"}]}, "n2b": {"speaker": "current_roommate", "text": "That sounds great, our kitchen could use more use! What''s your schedule like?", "text_fr": "Ça a l''air super, notre cuisine pourrait servir davantage ! Ton emploi du temps ressemble à quoi ?", "choices": [{"text": "Classes in the mornings mostly, free afternoons and evenings.", "text_fr": "Cours surtout le matin, après-midis et soirées libres.", "next": "n3"}]}, "n3": {"speaker": "current_roommate", "text": "Good to know. How do you feel about having guests over occasionally?", "text_fr": "Bon à savoir. Tu penses quoi du fait d''avoir des invités occasionnellement ?", "choices": [{"text": "I''m fine with it, as long as it''s not too frequent or too late.", "text_fr": "Ça me va, tant que ce n''est pas trop fréquent ou trop tard.", "next": "n4"}, {"text": "I don''t really have many guests, I''m pretty low-key.", "text_fr": "Je n''ai pas vraiment beaucoup d''invités, je suis assez discret.", "next": "n4"}]}, "n4": {"speaker": "current_roommate", "text": "That works for us. What about cleanliness — how would you describe yourself?", "text_fr": "Ça nous va. Et pour la propreté — comment tu te décrirais ?", "choices": [{"text": "Pretty organized, I like keeping shared spaces tidy.", "text_fr": "Assez organisé, j''aime garder les espaces communs propres.", "next": "n5"}, {"text": "I do my best, though I''m not obsessively neat.", "text_fr": "Je fais de mon mieux, même si je ne suis pas obsessionnellement ordonné.", "next": "n5"}]}, "n5": {"speaker": "current_roommate", "text": "Honest answer, I appreciate that. Do you have any pets, or plan to?", "text_fr": "Réponse honnête, j''apprécie. Tu as des animaux, ou tu prévois d''en avoir ?", "choices": [{"text": "No pets, and I''m not planning on getting any soon.", "text_fr": "Pas d''animaux, et je ne prévois pas d''en avoir bientôt.", "next": "n6"}, {"text": "I have a cat actually — is that a dealbreaker?", "text_fr": "J''ai un chat en fait — c''est rédhibitoire ?", "next": "n6b"}]}, "n6": {"speaker": "current_roommate", "text": "Perfect, that keeps things simple. Any questions for us about the place?", "text_fr": "Parfait, ça simplifie les choses. Des questions pour nous à propos de l''appart ?", "choices": [{"text": "What''s the rent split like, and are utilities included?", "text_fr": "Le loyer se partage comment, et les charges sont incluses ?", "next": "n7"}]}, "n6b": {"speaker": "current_roommate", "text": "Actually, one of us has a mild cat allergy, so that could be tricky.", "text_fr": "En fait, l''un de nous a une légère allergie aux chats, donc ça pourrait être compliqué.", "choices": [{"text": "I understand, that''s important to know upfront, thanks for being honest.", "text_fr": "Je comprends, c''est important de le savoir dès le départ, merci d''être honnête.", "next": "n7"}]}, "n7": {"speaker": "current_roommate", "text": "Rent is split evenly, and utilities are shared through an app that tracks it fairly.", "text_fr": "Le loyer est partagé équitablement, et les charges sont partagées via une appli qui suit ça équitablement.", "choices": [{"text": "That sounds really well organized, I like that.", "text_fr": "Ça a l''air vraiment bien organisé, j''aime ça.", "next": "n8"}]}, "n8": {"speaker": "current_roommate", "text": "We try to keep things fair and transparent here. So, what do you think overall?", "text_fr": "On essaie de garder les choses justes et transparentes ici. Alors, qu''est-ce que tu penses globalement ?", "choices": [{"text": "I really like the vibe here, I''d love to move forward if possible.", "text_fr": "J''aime vraiment l''ambiance ici, j''aimerais avancer si possible.", "next": "n9"}, {"text": "I need a little time to think, but I''m definitely interested.", "text_fr": "J''ai besoin d''un peu de temps pour réfléchir, mais je suis définitivement intéressé.", "next": "n9"}]}, "n9": {"speaker": "current_roommate", "text": "That''s great to hear! We''ll chat with the other applicants and get back to you soon.", "text_fr": "C''est génial à entendre ! On va discuter avec les autres candidats et te recontacter bientôt.", "choices": [{"text": "Sounds good, thank you for having me over!", "text_fr": "Ça marche, merci de m''avoir reçu !", "next": "end_positive"}]}, "end_positive": {"speaker": "current_roommate", "text": "Of course, it was great meeting you. We''ll be in touch soon!", "text_fr": "Bien sûr, c''était super de te rencontrer. On te recontacte bientôt !", "end": true, "ending_label": "Bonne impression laissée aux colocataires 🏠✅"}}}'::jsonb, is_playable = true
where title = 'Une visite d''''appartement en colocation'
  and theme_id = (select id from scenario_themes where position = 6 and language_id = (select id from languages where code = 'en'));
